{
  "hypotheses": [
    {
      "name": "Organizational Capital and Deferred Revenue Synergy",
      "mechanism": "Firms with high organizational capital (OrgCap) and rising deferred revenue (DelDRC) are better positioned to monetize human and process intangibles through prepayments or subscriptions. The composite captures firms more likely to convert intangible value into future cash, a dynamic not fully exploited by either primitive alone.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "OrgCap"},
          {"weight": 0.5, "primitive": "DelDRC"},
          {"weight": -0.5, "primitive": "DelCOL"}
        ],
        "regime": "TERM_SPREAD_POSITIVE",
        "vol_target": true
      },
      "auxiliary_predictions": [
        {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
        {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
        {"type": "correlation", "primitive": "OrgCap", "bound": "below", "threshold": 0.3}
      ],
      "expected_annualized_sharpe": 0.75,
      "expected_decay_half_life_months": 36
    },
    {
      "name": "Inventory Management in Industry Concentration",
      "mechanism": "Firms that show prudent inventory management (low InvGrowth) in highly concentrated industries (HerfAsset) avoid price wars and are better at passing costs through. The interaction targets firms with genuine supply-side pricing power not isolated in either measure individually.",
      "expression": {
        "terms": [
          {"weight": -1.0, "primitive": "InvGrowth"},
          {"weight": 1.0, "primitive": "HerfAsset"}
        ],
        "regime": null,
        "vol_target": true
      },
      "auxiliary_predictions": [
        {"type": "size_segment", "segment": "mega", "direction": "stronger"},
        {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
        {"type": "correlation", "primitive": "HerfAsset", "bound": "below", "threshold": 0.3}
      ],
      "expected_annualized_sharpe": 0.60,
      "expected_decay_half_life_months": 42
    },
    {
      "name": "Analyst Disagreement with Option Market Sentiment",
      "mechanism": "When forecast dispersion among analysts (ForecastDispersion) aligns with negative sentiment from the option market (SmileSlope), it identifies stocks where uncertainty is not fully priced. The composite exploits excess risk premia from information frictions between sell-side analysts and derivatives traders.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "ForecastDispersion"},
          {"weight": -0.5, "primitive": "SmileSlope"}
        ],
        "regime": "VIX_ABOVE_TRAILING_MEDIAN",
        "vol_target": true
      },
      "auxiliary_predictions": [
        {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
        {"type": "size_segment", "segment": "micro", "direction": "stronger"},
        {"type": "correlation", "primitive": "ForecastDispersion", "bound": "below", "threshold": 0.3}
      ],
      "expected_annualized_sharpe": 0.68,
      "expected_decay_half_life_months": 30
    },
    {
      "name": "Dividend Initiation with Low Equity Issuance",
      "mechanism": "Combining recent dividend initiation (DivInit) with low net equity financing (NetEquityFinance) isolates signals of shareholder commitment not driven by dilution. This composite targets firms genuinely able to sustain payouts versus those funding them with new equity.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "DivInit"},
          {"weight": -1.0, "primitive": "NetEquityFinance"}
        ],
        "regime": "MKT_TRAILING_12M_DOWN",
        "vol_target": false
      },
      "auxiliary_predictions": [
        {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
        {"type": "international", "region": "emerging", "direction": "same_sign"},
        {"type": "subperiod_consistency"}
      ],
      "expected_annualized_sharpe": 0.55,
      "expected_decay_half_life_months": 54
    },
    {
      "name": "Cash Productivity and Deferred Tax Benefit",
      "mechanism": "Firms with high cash productivity (CashProd) and recent increases in deferred tax assets (ChTax) signal sustainable, tax-efficient operational efficiency. The composite leverages the joint effect of operational quality and forward-looking tax shields.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "CashProd"},
          {"weight": 0.5, "primitive": "ChTax"}
        ],
        "regime": null,
        "vol_target": true
      },
      "auxiliary_predictions": [
        {"type": "international", "region": "developed_ex_us", "direction": "opposite_sign"},
        {"type": "correlation", "primitive": "CashProd", "bound": "below", "threshold": 0.3},
        {"type": "subperiod_consistency"}
      ],
      "expected_annualized_sharpe": 0.57,
      "expected_decay_half_life_months": 36
    },
    {
      "name": "Customer Momentum with Operating Leverage",
      "mechanism": "Stocks with strong customer momentum (iomom_cust) and high operating leverage (OPLeverage) benefit disproportionately from positive demand shocks, as fixed costs amplify customer flow-through. The composite identifies firms poised for outsized earnings surprises.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "iomom_cust"},
          {"weight": 0.5, "primitive": "OPLeverage"}
        ],
        "regime": "VIX_BELOW_TRAILING_MEDIAN",
        "vol_target": false
      },
      "auxiliary_predictions": [
        {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
        {"type": "size_segment", "segment": "small", "direction": "stronger"},
        {"type": "correlation", "primitive": "OPLeverage", "bound": "below", "threshold": 0.3}
      ],
      "expected_annualized_sharpe": 0.66,
      "expected_decay_half_life_months": 24
    },
    {
      "name": "R&D Ability and Patent Conversion",
      "mechanism": "Firms high in R&D ability (RDAbility) that also show high patent output relative to R&D expenses (PatentsRD) are those most capable of converting innovation investment into protectable assets, not just spending for its own sake. The composite captures productive innovation efficiency.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "RDAbility"},
          {"weight": 1.0, "primitive": "PatentsRD"},
          {"weight": -0.5, "primitive": "RD"}
        ],
        "regime": null,
        "vol_target": true
      },
      "auxiliary_predictions": [
        {"type": "size_segment", "segment": "large", "direction": "stronger"},
        {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
        {"type": "subperiod_consistency"}
      ],
      "expected_annualized_sharpe": 0.65,
      "expected_decay_half_life_months": 60
    },
    {
      "name": "Short Interest, Price Delay, and Realized Volatility",
      "mechanism": "Stocks with high short interest (ShortInterest), significant price delay (PriceDelayRsq), and elevated realized volatility (RealizedVol) are likely under temporary price pressure from overextended shorts and inefficient price discovery. The composite exploits a reversion effect as shorts cover in volatile, stale-priced stocks.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "ShortInterest"},
          {"weight": 0.5, "primitive": "PriceDelayRsq"},
          {"weight": 1.0, "primitive": "RealizedVol"}
        ],
        "regime": null,
        "vol_target": false
      },
      "auxiliary_predictions": [
        {"type": "size_segment", "segment": "micro", "direction": "stronger"},
        {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
        {"type": "correlation", "primitive": "ShortInterest", "bound": "below", "threshold": 0.3}
      ],
      "expected_annualized_sharpe": 0.58,
      "expected_decay_half_life_months": 18
    }
  ]
}
